import webpush from 'web-push';
import { config } from './config.js';
import { pool } from './db.js';
import { log } from './log.js';

/**
 * Web Push (the notifications a phone shows even when the app is closed). The server signs every
 * message with a VAPID key pair; it comes from VAPID_PUBLIC_KEY / VAPID_PRIVATE_KEY in .env or,
 * when those are empty, from a pair generated on first start and kept in app_settings. Changing
 * the pair invalidates every existing subscription, so it is never regenerated by itself.
 */
let publicKey = '';

export async function initPush(): Promise<void> {
  let pub = config.vapid.publicKey;
  let priv = config.vapid.privateKey;
  if (!pub || !priv) {
    const { rows } = await pool.query<{ key: string; value: string }>(
      `SELECT key, value FROM app_settings WHERE key IN ('vapid_public', 'vapid_private')`,
    );
    pub = rows.find((r) => r.key === 'vapid_public')?.value ?? '';
    priv = rows.find((r) => r.key === 'vapid_private')?.value ?? '';
  }
  if (!pub || !priv) {
    const pair = webpush.generateVAPIDKeys();
    await pool.query(
      `INSERT INTO app_settings (key, value) VALUES ('vapid_public', $1), ('vapid_private', $2)
       ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value`,
      [pair.publicKey, pair.privateKey],
    );
    pub = pair.publicKey;
    priv = pair.privateKey;
    log.info('generated a new web push (VAPID) key pair');
  }
  webpush.setVapidDetails(config.vapid.subject, pub, priv);
  publicKey = pub;
}

export const pushPublicKey = (): string => publicKey;

export interface PushPayload {
  title: string;
  body: string;
  /** notifications with the same tag replace each other on the device */
  tag?: string;
  /** path opened when the notification is tapped */
  url?: string;
}

interface SubscriptionRow {
  id: number;
  endpoint: string;
  p256dh: string;
  auth: string;
}

/** Sends the payload to every device of the user. Dead subscriptions are removed on the way. */
export async function sendPushToUser(userId: number, payload: PushPayload): Promise<{ sent: number; failed: number }> {
  const { rows } = await pool.query<SubscriptionRow>(
    'SELECT id, endpoint, p256dh, auth FROM push_subscriptions WHERE user_id = $1',
    [userId],
  );
  let sent = 0;
  let failed = 0;
  const body = JSON.stringify({ ...payload, url: payload.url ?? '/' });
  await Promise.all(
    rows.map(async (s) => {
      try {
        await webpush.sendNotification({ endpoint: s.endpoint, keys: { p256dh: s.p256dh, auth: s.auth } }, body, {
          TTL: 60 * 60,
          urgency: 'high',
        });
        await pool.query('UPDATE push_subscriptions SET last_used_at = now(), failures = 0 WHERE id = $1', [s.id]);
        sent++;
      } catch (err) {
        failed++;
        const status = (err as { statusCode?: number }).statusCode;
        if (status === 404 || status === 410) {
          await pool.query('DELETE FROM push_subscriptions WHERE id = $1', [s.id]);
          log.info({ user: userId, subscription: s.id }, 'push subscription expired, removed');
        } else {
          await pool.query('DELETE FROM push_subscriptions WHERE id = $1 AND failures >= 4', [s.id]);
          await pool.query('UPDATE push_subscriptions SET failures = failures + 1 WHERE id = $1', [s.id]);
          log.warn({ user: userId, subscription: s.id, status, reason: (err as Error).message }, 'push failed');
        }
      }
    }),
  );
  return { sent, failed };
}
